# Check for vertical symmetry (columns)
def has_vertical_symmetry(grid):
    height = len(grid)
    width = len(grid[0])
    for col in range(width // 2):
        for row in range(height):
            if grid[row][col] != grid[row][width - 1 - col]:
                return False
    return True

